import{_ as a,H as s,f as t,i}from"./chunks/framework.BauLNg70.js";const u=JSON.parse('{"title":"Targeting your mod to a specific game","description":"","frontmatter":{},"headers":[],"relativePath":"targeting-games.md","filePath":"targeting-games.md"}'),o={name:"targeting-games.md"};function n(l,e,h,p,r,d){return s(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="targeting-your-mod-to-a-specific-game" tabindex="-1">Targeting your mod to a specific game <a class="header-anchor" href="#targeting-your-mod-to-a-specific-game" aria-label="Permalink to &quot;Targeting your mod to a specific game&quot;">​</a></h1><p>Your mod declares which game it targets. This guide covers how to pick the right target and why your mod will work in different bundles (standalone, collections) without you needing to publish multiple copies.</p><hr><h2 id="target-gameid-—-the-key-decision" tabindex="-1"><code>target.gameId</code> — the key decision <a class="header-anchor" href="#target-gameid-—-the-key-decision" aria-label="Permalink to &quot;`target.gameId` — the key decision&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;gameId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;snake-classic&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;gameVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;^2.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>gameId</code> is the game&#39;s <strong>logical identity</strong> within the framework, not its commercial name nor AppID. Immutable throughout the game&#39;s lifetime.</p><p>You&#39;ll find it in:</p><ul><li><code>docs/games/&lt;id&gt;/README.md</code> of the studio&#39;s repo.</li><li>The game&#39;s &quot;About&quot; screen (usually shows it).</li><li>The SDK / host-api-changelog docs.</li></ul><p>When in doubt: ask the studio. It&#39;s public information.</p><hr><h2 id="why-you-don-t-target-the-bundle" tabindex="-1">Why you don&#39;t target the bundle <a class="header-anchor" href="#why-you-don-t-target-the-bundle" aria-label="Permalink to &quot;Why you don&#39;t target the bundle&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❌ &quot;target.gameId&quot;: &quot;classics-collection&quot;</span></span>\n<span class="line"><span>❌ &quot;target.steamAppId&quot;: 1234567</span></span>\n<span class="line"><span>✅ &quot;target.gameId&quot;: &quot;snake-classic&quot;</span></span></code></pre></div><p>The framework is designed so the same mod works in:</p><ul><li>Snake Classic standalone (Steam App ID 1234567)</li><li>Snake Classic inside Classics Collection (Steam App ID 4707310)</li></ul><p>Targeting the logical <code>gameId</code> guarantees both with no effort. Targeting the bundle would tie you to one.</p><hr><h2 id="workshop-and-steam-appids" tabindex="-1">Workshop and Steam AppIDs <a class="header-anchor" href="#workshop-and-steam-appids" aria-label="Permalink to &quot;Workshop and Steam AppIDs&quot;">​</a></h2><p>Workshop publishes against an AppID. Your mod appears under the AppID you choose to publish.</p><p>The framework maintains an internal mapping:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gameId &#39;snake-classic&#39; → discovered AppIDs: [1234567, 4707310]</span></span></code></pre></div><p>This means: if you publish your mod on Workshop under AppID 1234567 (standalone), Classics Collection players (AppID 4707310) will also see it and can install it.</p><p>Recommendation: publish under the <strong>standalone</strong> AppID (usually has more distribution). If only the collection exists, publish against that one.</p><hr><h2 id="target-gameversion-—-compatible-range" tabindex="-1"><code>target.gameVersion</code> — compatible range <a class="header-anchor" href="#target-gameversion-—-compatible-range" aria-label="Permalink to &quot;`target.gameVersion` — compatible range&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;gameId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;snake-classic&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;gameVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;^2.0.0&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>SemVer range:</p><ul><li><code>^2.0.0</code>: compatible with 2.0.0, 2.5.7, 2.99.99 — NOT 3.0.0.</li><li><code>~2.0.0</code>: compatible with 2.0.x — NOT 2.1.0.</li><li><code>&gt;=2.0.0 &lt;3.0.0</code>: explicit.</li></ul><p>Use the widest range you&#39;ve tested. If you only tested with 2.3.0:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;gameVersion&quot;: &quot;^2.3.0&quot;</span><span>   // good</span></span>\n<span class="line"><span>&quot;gameVersion&quot;: &quot;^2.0.0&quot;</span><span>   // optimistic; might break with 2.0.x</span></span></code></pre></div><p>After testing with a new game version, <strong>publish a new version of your mod</strong> with the widened range.</p><hr><h2 id="requires-hostapi-—-the-other-half-of-the-contract" tabindex="-1"><code>requires.hostApi</code> — the other half of the contract <a class="header-anchor" href="#requires-hostapi-—-the-other-half-of-the-contract" aria-label="Permalink to &quot;`requires.hostApi` — the other half of the contract&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;requires&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;hostApi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;^1.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>This compares against the game&#39;s <code>host.api.version</code>. If the game&#39;s host API jumps from 1.x to 2.x (breaking), your mod is marked <code>incompatible</code> until you publish a version with <code>requires.hostApi: &#39;^2.0.0&#39;</code>.</p><p>The studio maintains <code>docs/games/&lt;id&gt;/host-api-changelog.md</code> with each change. Follow it if you want to know when you need to re-publish.</p><hr><h2 id="requires-dlcs-—-dlc-dependencies" tabindex="-1"><code>requires.dlcs</code> — DLC dependencies <a class="header-anchor" href="#requires-dlcs-—-dlc-dependencies" aria-label="Permalink to &quot;`requires.dlcs` — DLC dependencies&quot;">​</a></h2><p>If your mod modifies DLC content:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;requires&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;dlcs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;snake-classic.endless-plus&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre></div><p>The loader checks <code>EntitlementService.hasAccess()</code> before activating your mod. If the DLC isn&#39;t owned, the mod appears &quot;requires DLC X&quot; with a clear message to the player.</p><p>For mods that <strong>work without the DLC but gain features with it</strong>: don&#39;t declare it as required. Inspect <code>host.entitlements.getActiveDlcs()</code> in your code and adapt behavior.</p><hr><h2 id="multi-game-targets" tabindex="-1">Multi-game targets <a class="header-anchor" href="#multi-game-targets" aria-label="Permalink to &quot;Multi-game targets&quot;">​</a></h2><p><strong>Not supported</strong>: a mod targets <strong>one single game</strong>. If you want it to work on multiple framework games, publish multiple mods (one per game) sharing common code you maintain.</p><p>Reason: every game has its own host API, its own policy, its own surfaces. &quot;A universal mod&quot; would be fragile.</p><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><ul><li>Target the logical <code>gameId</code>, not the AppID nor the commercial name.</li><li>SemVer ranges in <code>target.gameVersion</code> and <code>requires.hostApi</code>.</li><li>Your mod automatically works in standalone and in bundles (Classics Collection) that mount that game.</li><li>Workshop mapping: publish against one AppID, discovered from all.</li><li>Required DLCs declared in <code>requires.dlcs[]</code>.</li></ul>',48)])])}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
